import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    v = []
    for _ in range(n):
        v.append(int(next(iterator)))

    adj = [[] for _ in range(n)]
    for _ in range(m):
        x = int(next(iterator)) - 1
        y = int(next(iterator)) - 1
        adj[x].append(y)
        adj[y].append(x)

    total_energy = 0
    for i in range(n):
        for neighbor in adj[i]:
            if v[neighbor] < v[i]:
                total_energy += v[neighbor]
            else:
                total_energy += v[i]

    print(total_energy)

if __name__ == "__main__":
    main()
